// The Braided Divide. All authoring is Source-local METRES. Runtime cells are
// converted at the boundary, never mixed into this construction manifest.
// Ground, raised solid work, actual model tops and the passages below them are
// separate surfaces. Merely standing under a crossing cannot acquire its floor.
import { SOURCE_HANGING_SHORE } from './source-hanging-shore.js';

const freeze = Object.freeze;
const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
const EPS = 1e-6;
export const SOURCE_BRAIDED_DIVIDE = freeze({
  version: 1, minX: -90, maxX: 90, frontZ: SOURCE_HANGING_SHORE.bank.frontZ,
  backZ: -540, length: 150, lower: 4.2, middle: 9, upper: 15.2,
  underside: SOURCE_HANGING_SHORE.bank.underside,
  finalRise: freeze({ from: 118, to: 146 }),
  court: freeze({ x: -12, z: -465, floor: 4.2, minX: -12, maxX: 12, from: 67, to: 84 }),
  crossings: freeze([freeze({ id: 'case-crossing', depth: 50, floor: 9 }), freeze({ id: 'piano-crossing', depth: 107, floor: 15.2 })]),
});
const S = SOURCE_BRAIDED_DIVIDE;
export const sourceDivideDepth = z => S.frontZ - Number(z);
export const sourceDivideZ = depth => S.frontZ - Number(depth);
export function sourceDivideContains(x, z, margin = 0) {
  const d = sourceDivideDepth(z);
  return Number.isFinite(x) && Number.isFinite(z) && x >= S.minX + margin && x <= S.maxX - margin && d >= 0 && d <= S.length;
}
export function sourceDivideFloorAt(x, z) {
  if (!sourceDivideContains(x, z)) return null;
  const d = sourceDivideDepth(z);
  return S.lower + (S.upper - S.lower) * clamp((d - S.finalRise.from) / (S.finalRise.to - S.finalRise.from), 0, 1);
}

const rectangle = (minX, maxX, from, to) => [[minX, sourceDivideZ(from)], [maxX, sourceDivideZ(from)], [maxX, sourceDivideZ(to)], [minX, sourceDivideZ(to)]];
const colour = freeze({ bank: [.24, .27, .25], ramp: [.31, .34, .30], crossing: [.27, .29, .25], court: [.32, .33, .29], ground: [.19, .22, .20], support: [.23, .25, .23] });
const solids = [];
function solid(id, polygon, bottom, top, kind = 'bank', extra = {}) {
  const result = { id, polygon, bottom, top, kind, color: colour[kind] || colour.bank, ...extra };
  solids.push(result); return result;
}
const box = (id, minX, maxX, from, to, top, kind = 'bank', bottom = S.lower) => solid(id, rectangle(minX, maxX, from, to), bottom, () => top, kind);
const ramp = (id, minX, maxX, from, to, low, high) => solid(id, rectangle(minX, maxX, from, to), S.lower, (_x, z) => low + (high - low) * clamp((sourceDivideDepth(z) - from) / (to - from), 0, 1), 'ramp', { from, to, low, high });

box('west-middle-bank', -88, -26, 42, 82, S.middle);
box('east-middle-bank', 24, 88, 47, 98, S.middle);
box('west-middle-projection', -26, -18, 58, 65, S.middle);
box('east-middle-projection', 12, 24, 86, 93, S.middle);
box('west-upper-bank', -88, -32, 106, 150, S.upper);
box('east-upper-bank', 20, 88, 108, 150, S.upper);
ramp('west-front-ramp', -42, -24, 22, 42, S.lower, S.middle);
ramp('west-outer-ramp', -88, -74, 22, 42, S.lower, S.middle);
ramp('east-front-ramp', 24, 44, 27, 47, S.lower, S.middle);
ramp('east-outer-ramp', 74, 88, 27, 47, S.lower, S.middle);
ramp('west-upper-ramp', -66, -34, 80, 106, S.middle, S.upper);
ramp('east-upper-ramp', 40, 72, 82, 108, S.middle, S.upper);
// Three shallow courses form only the west side of the Listening Court. Its
// north, east and south remain open; neither a battle box nor a completion gate.
box('court-low-course', -18, -12.5, 68, 82, 4.5, 'court');
box('court-middle-course', -22, -18, 68, 82, 4.8, 'court');
box('court-high-course', -26, -22, 68, 82, 5.1, 'court');

// These two surfaces are actual native GLB faces: the case's cloth lining at
// local y=.2225 and the piano's lid at y=1.1375. Their wings meet those faces,
// rather than covering the mesh with a second invisible rectangular platform.
const props = [];
function prop(id, mesh, x, depth, y, scale = 1, extra = {}) {
  const result = freeze({ id, mesh, kind: 'braided-model', x, y, z: sourceDivideZ(depth), scale, yaw: 0, pitch: 0, roll: 0, ...extra });
  props.push(result); return result;
}
const caseCrossing = prop('divide-case-crossing', 'open_instrument_case', 0, 50, 6.33, 1, { scaleX: 32, scaleY: 12, scaleZ: 14, kind: 'crossing' });
box('case-west-wing', -30, -18.4, 47.48, 52.52, 9, 'crossing', 8.4);
box('case-east-wing', 18.4, 30, 47.48, 52.52, 9, 'crossing', 8.4);
const pianoCrossing = prop('divide-piano-crossing', 'grand_piano', 0, 107, 6.1, 1, { scaleX: 10, scaleY: 8, scaleZ: 22, yaw: Math.PI / 2, kind: 'crossing' });

function transformPoint(p, entry) {
  let [x, y, z] = p;
  x *= entry.scaleX ?? entry.scale; y *= entry.scaleY ?? entry.scale; z *= entry.scaleZ ?? entry.scale;
  let c = Math.cos(entry.roll), s = Math.sin(entry.roll); [x, y] = [x * c - y * s, x * s + y * c];
  c = Math.cos(entry.pitch); s = Math.sin(entry.pitch); [y, z] = [y * c - z * s, y * s + z * c];
  c = Math.cos(entry.yaw); s = Math.sin(entry.yaw); [x, z] = [x * c + z * s, -x * s + z * c];
  return [entry.x + x, entry.y + y, entry.z + z];
}
function pianoLidPolygon() {
  const c = Math.cos(.10), s = Math.sin(.10);
  return [[-.725, .86], [.725, .86], [.725, -.86], [-.725, -.86]].map(([x, z]) => {
    const p = transformPoint([.18 + x * c - z * s, 1.1375, .12 + x * s + z * c], pianoCrossing);
    return [p[0], p[2]];
  });
}
function intervalAtZ(polygon, z) {
  const xs = [];
  for (let i = 0; i < polygon.length; i++) {
    const a = polygon[i], b = polygon[(i + 1) % polygon.length];
    if (z < Math.min(a[1], b[1]) - EPS || z > Math.max(a[1], b[1]) + EPS || Math.abs(b[1] - a[1]) < EPS) continue;
    xs.push(a[0] + (b[0] - a[0]) * (z - a[1]) / (b[1] - a[1]));
  }
  return [Math.min(...xs), Math.max(...xs)];
}
const lid = pianoLidPolygon(), zNear = sourceDivideZ(106), zFar = sourceDivideZ(110);
const near = intervalAtZ(lid, zNear), far = intervalAtZ(lid, zFar);
solid('piano-west-wing', [[-40, zNear], [near[0], zNear], [far[0], zFar], [-40, zFar]], 14.6, () => 15.2, 'crossing');
solid('piano-east-wing', [[near[1], zNear], [46, zNear], [46, zFar], [far[1], zFar]], 14.6, () => 15.2, 'crossing');
// The instrument's three legs land on finite, visibly rendered source piers.
for (const [index, x, z] of [[0, -.62, -.70], [1, .58, -.55], [2, .42, .72]]) {
  const point = transformPoint([x, .005, z], pianoCrossing), d = sourceDivideDepth(point[2]);
  box(`piano-leg-pier-${index}`, point[0] - 1.05, point[0] + 1.05, d - .5, d + .5, point[1], 'support');
}

// Existing hero families remain in their recognisable regions. Their supports
